    if is_datetime64_any_dtype(other) and is_timedelta64_dtype(self.dtype):
        # ndarray[datetime64] cannot be subtracted from TimedeltaArray, so
        # we need to wrap in DatetimeArray/Index and flip the operation.
        if not isinstance(other, DatetimeLikeArrayMixin):
            from pandas.core.arrays import DatetimeArray
            other = DatetimeArray(other)
        return other - self
    elif (
        is_datetime64_any_dtype(self.dtype)
        and hasattr(other, "dtype")
        and not is_datetime64_any_dtype(other.dtype)
    ):
        # Raise error if other is not a datetime type when self is datetime
        raise TypeError(
            "cannot subtract {cls} from {typ}".format(
                cls=type(self).__name__, typ=type(other).__name__
            )
        )
    elif is_period_dtype(self.dtype) and is_timedelta64_dtype(other):
        # Raise error if trying to subtract timedelta from period type
        raise TypeError(
            "cannot subtract {cls} from {dtype}".format(
                cls=type(self).__name__, dtype=other.dtype
            )
        )
    elif is_timedelta64_dtype(self.dtype):
        if lib.is_integer(other) or is_integer_dtype(other):
            # need to subtract before negating, since that flips freq
            return -(self - other)
        else:
            # Handling subtraction for other numeric or datetime-like inputs
            return (-self) + other
    # Default case: return negated result of subtraction
    return -(self - other)
