def __rsub__(self, other):
    if is_datetime64_any_dtype(other) and is_timedelta64_dtype(self.dtype):
        # ndarray[datetime64] cannot be subtracted from self, so
        # we need to wrap in DatetimeArray/Index and flip the operation
        if not isinstance(other, DatetimeLikeArrayMixin):
            # Avoid down-casting DatetimeIndex
            from pandas.core.arrays import DatetimeArray

            other = DatetimeArray(other)
        return other - self
    elif is_datetime64_any_dtype(self.dtype) and hasattr(other, "dtype") and not is_datetime64_any_dtype(other.dtype):
        # GH#19959 datetime - datetime is well-defined as timedelta,
        # but any other type - datetime is not well-defined.
        raise TypeError(
            "cannot subtract {cls} from {typ}".format(
                cls=type(self).__name__, typ=type(other).__name__
            )
        )
    elif is_period_dtype(self.dtype) and is_timedelta64_dtype(other):
        # Raise TypeError for invalid operation
        raise TypeError(
            "cannot subtract {cls} from {dtype}".format(
                cls=type(self).__name__, dtype=other.dtype
            )
        )
    elif is_timedelta64_dtype(self.dtype):
        if lib.is_integer(other) or is_integer_dtype(other):
            return -(self - other)

        return (-self) + other

    # Handle case where 'other' can be a datetime-like or numpy.datetime64
    if isinstance(other, (datetime.datetime, np.datetime64)):
        return -(self.astype('timedelta64[ns]') + other)

    return -(self - other)
